const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const omaha_area = ee.Geometry.Polygon(
    [
      [-96.48, 41.51],
      [-96.00, 41.51],
      [-96.00, 41.00],
      [-96.48, 41.00],
      [-96.48, 41.51]
    ]
  );

  // Approximate geometry for the area between Elkhorn and Platte Rivers near Omaha
  // This polygon covers parts of the confluence area south-west of Omaha
  const geometry = ee.Geometry.Polygon(
    [
      [-96.536, 41.196],
      [-96.380, 41.250],
      [-96.326, 41.077],
      [-96.474, 41.020],
      [-96.536, 41.196]
    ]
  );

  const date_2019_start = '2019-03-01';
  const date_2019_end = '2019-03-31'; // Broader window for 2019 to find a good image
  const date_2018_start = '2018-03-01';
  const date_2018_end = '2018-03-31';

  const scale = 30; // Sentinel-2 resolution
  const water_threshold = 0; // MNDWI > 0 for water detection

  // Function to mask clouds in Sentinel-2 images (L1C - QA60 band)
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
      .select(['B3', 'B11'])
      .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate MNDWI
  function calculateMNDWI(image) {
    // MNDWI = (Green - SWIR1) / (Green + SWIR1)
    // Sentinel-2: B3 is Green, B11 is SWIR1
    return image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
  }

  // 2. Data Acquisition & Check
  let collection_2019 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(geometry)
    .filterDate(date_2019_start, date_2019_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Filter for less cloudy images
    .map(maskS2clouds);

  let collection_2018 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(geometry)
    .filterDate(date_2018_start, date_2018_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2clouds);

  const size_2019 = await collection_2019.size().getInfo();
  const size_2018 = await collection_2018.size().getInfo();

  if (size_2019 === 0 || size_2018 === 0) {
    console.log(`2019 Images: ${size_2019}`);
    console.log(`2018 Images: ${size_2018}`);
    console.log("C1");
    return;
  }

  // To best represent "March 16, 2019" as specified, we'll try to find the least cloudy image closest to that date.
  // For "March 2018", a monthly median composite is appropriate.

  // For 2019, get the least cloudy image (or a median if multiple images are good)
  const image_2019_raw = collection_2019
    .sort('system:time_start', true) // Sort by date to get closest to March 1st if needed, or by cloudiness
    .mosaic(); // Use mosaic to handle potential multiple images after filtering

  // For 2018, create a median composite for the entire month
  const image_2018_raw = collection_2018.median();

  // Calculate MNDWI for both images
  const mndwi_2019 = calculateMNDWI(image_2019_raw).clip(geometry);
  const mndwi_2018 = calculateMNDWI(image_2018_raw).clip(geometry);

  // Classify water based on threshold
  const water_2019 = mndwi_2019.gt(water_threshold);
  const water_2018 = mndwi_2018.gt(water_threshold);

  // Calculate water area (in square kilometers)
  const pixel_area_image = ee.Image.pixelArea().divide(1e6); // Square meters to square kilometers

  const water_area_2019 = water_2019.multiply(pixel_area_image)
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    })
    .get('MNDWI');

  const water_area_2018 = water_2018.multiply(pixel_area_image)
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    })
    .get('MNDWI');

  const area_2019_val = await water_area_2019.getInfo();
  const area_2018_val = await water_area_2018.getInfo();

  // Validate pixel counts for the water masks before area calculation (to catch C2 scenarios)
  const count_2019 = await water_2019.reduceRegion({ reducer: ee.Reducer.count(), geometry: geometry, scale: scale, maxPixels: 1e9 }).get('MNDWI').getInfo();
  const count_2018 = await water_2018.reduceRegion({ reducer: ee.Reducer.count(), geometry: geometry, scale: scale, maxPixels: 1e9 }).get('MNDWI').getInfo();

  if (count_2019 === 0 && count_2018 === 0) {
    console.log("No valid pixels for water classification in both periods after masking.");
    console.log("C2");
    return;
  } else if (count_2019 === 0) {
    console.log("No valid pixels for water classification in 2019 after masking.");
    // Even if 2018 has pixels, if 2019 has none, comparison is problematic for increase.
    // However, if 2018 has water and 2019 has none, it's a decrease, not C2.
    // We should only report C2 if *no* pixels remain for calculation.
    // If water_area_2019 is 0, but valid pixels existed, it means 0 water.
  } else if (count_2018 === 0) {
    console.log("No valid pixels for water classification in 2018 after masking.");
  }


  // 5. Validation & Final Answer
  if (area_2019_val === null || area_2018_val === null || isNaN(area_2019_val) || isNaN(area_2018_val)) {
    console.log(`2019 Water Area: ${area_2019_val}`);
    console.log(`2018 Water Area: ${area_2018_val}`);
    console.log("C3"); // Calculation failure
    return;
  }

  console.log(`2019 Images: ${size_2019}`);
  console.log(`2018 Images: ${size_2018}`);
  console.log(`2019 Water Area (sq km): ${area_2019_val.toFixed(2)}`);
  console.log(`2018 Water Area (sq km): ${area_2018_val.toFixed(2)}`);

  if (area_2019_val > area_2018_val) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
